import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.Cr9EE2ob.js";const u=JSON.parse('{"title":"Auth Penalty (cross-pod IP backoff)","description":"yarilo-auth can enforce a per-client-IP exponential backoff on failed auth attempts. The counter lives in the yarilo-warden service so a single attacker…","frontmatter":{"outline":[2,4],"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/auth/penalty.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/auth/penalty.html"}],["meta",{"property":"og:title","content":"Auth Penalty (cross-pod IP backoff)"}],["meta",{"name":"twitter:title","content":"Auth Penalty (cross-pod IP backoff)"}],["meta",{"property":"og:description","content":"yarilo-auth can enforce a per-client-IP exponential backoff on failed auth attempts. The counter lives in the yarilo-warden service so a single attacker…"}],["meta",{"name":"twitter:description","content":"yarilo-auth can enforce a per-client-IP exponential backoff on failed auth attempts. The counter lives in the yarilo-warden service so a single attacker…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/auth/penalty.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/auth/penalty.html\\",\\"headline\\":\\"Auth Penalty (cross-pod IP backoff)\\",\\"description\\":\\"yarilo-auth can enforce a per-client-IP exponential backoff on failed auth attempts. The counter lives in the yarilo-warden service so a single attacker…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Auth Penalty (cross-pod IP backoff)\\",\\"item\\":\\"https://doc.yarilomail.org/main/auth/penalty.html\\"}]}]}"]]},"headers":[],"relativePath":"auth/penalty.md","filePath":"auth/penalty.md","lastUpdated":1793450621000}'),i={name:"auth/penalty.md"};function l(r,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="auth-penalty-cross-pod-ip-backoff" tabindex="-1">Auth Penalty (cross-pod IP backoff) <a class="header-anchor" href="#auth-penalty-cross-pod-ip-backoff" aria-label="Permalink to &quot;Auth Penalty (cross-pod IP backoff)&quot;">​</a></h1><p><code>yarilo-auth</code> can enforce a per-client-IP exponential backoff on failed auth attempts. The counter lives in the <code>yarilo-warden</code> service so a single attacker IP pays the cost across every auth pod they land on - pod load-balancing does not let them reset by landing on a fresh pod.</p><h2 id="when-to-enable" tabindex="-1">When to enable <a class="header-anchor" href="#when-to-enable" aria-label="Permalink to &quot;When to enable&quot;">​</a></h2><p>A penalty store is useful when:</p><ul><li>the deployment runs more than one <code>yarilo-auth</code> pod and the process-local <code>auth_<wbr>failure_<wbr>delay</code> no longer covers all paths</li><li>the threat model includes credential stuffing from a single IP (or a small IP set) - exponential backoff makes 100 attempts/sec unprofitable</li><li><code>auth_<wbr>failure_<wbr>delay</code> alone amplifies legitimate retries too aggressively (delay applies to every attempt; penalty escalates only after sustained failure)</li></ul><p>When the deployment is one pod and <code>auth_<wbr>failure_<wbr>delay: 2</code> already covers the threat surface, the penalty store is overkill.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p><code>auth.<wbr>penalty</code> in <code>yarilo.<wbr>yaml</code> (or <code>components.<wbr>auth.<wbr>penalty</code> in Helm <code>values.<wbr>yaml</code>):</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  penalty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>The penalty store reuses the configured <code>warden_<wbr>service.<wbr>listen</code> address; no separate connection knob.</p><h3 id="auth.penalty.enabled" tabindex="-1"><code>enabled</code> <a class="header-anchor" href="#auth.penalty.enabled" aria-label="Permalink to &quot;\`enabled\` {#auth.penalty.enabled}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>components.auth.penalty.enabled</code></dd></dl></div><p>Opt-in. While <code>false</code>, every login skips both Lookup and Update (zero overhead). Turn it on once <code>yarilo-warden</code> is provisioned.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li><strong>Pre-passdb</strong>: Lookup the counter for the client IP. Sleep <code>PenaltyToSecs(count)</code> seconds before running the chain.</li><li><strong>Post-passdb</strong>: <ul><li><code>ResultOK</code> → Update(ip, 0) - reset to zero on success</li><li><code>ResultFail</code> → Update(ip, count+1) - capped server-side at <code>MaxPenalty</code> (4)</li><li><code>ResultTempFail</code> (passdb backend down) → <strong>no update</strong> - a backend outage is not the client&#39;s fault, and counting those would lock every client out for the decay window</li></ul></li><li><strong>Master-user flows exempt</strong> - admin sessions are never tarpitted regardless of unrelated IP noise</li></ul><h2 id="backoff-curve" tabindex="-1">Backoff curve <a class="header-anchor" href="#backoff-curve" aria-label="Permalink to &quot;Backoff curve&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Counter</th><th style="text-align:right;">Sleep before next attempt</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td style="text-align:right;">0s</td></tr><tr><td style="text-align:right;">1</td><td style="text-align:right;">2s</td></tr><tr><td style="text-align:right;">2</td><td style="text-align:right;">4s</td></tr><tr><td style="text-align:right;">3</td><td style="text-align:right;">8s</td></tr><tr><td style="text-align:right;">4+</td><td style="text-align:right;">15s (cap)</td></tr></tbody></table><p>Cumulative budget for the first four failures from a clean IP: <code>0 + 2 + 4 + 8 = 14s</code>. The fifth failure waits the cap (15s); the sixth, seventh, … each also wait the cap.</p><h2 id="decay" tabindex="-1">Decay <a class="header-anchor" href="#decay" aria-label="Permalink to &quot;Decay&quot;">​</a></h2><p>After 29 seconds with no Update, the entry is swept (matches the cumulative budget plus one cap window - once the worst-case backoff chain has fully played out, the entry no longer carries useful signal). Configurable via <code>warden.<wbr>WithPenaltyDecay</code> for testing, not exposed in the YAML - the default is well-calibrated.</p><p>A decayed entry returns 0 on the next Lookup, so a long-quiet IP starts fresh on its next attempt.</p><h2 id="wire-protocol" tabindex="-1">Wire protocol <a class="header-anchor" href="#wire-protocol" aria-label="Permalink to &quot;Wire protocol&quot;">​</a></h2><p><code>yarilo-warden</code> exposes two new verbs in protocol version 1.6:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PENALTY-LOOKUP &lt;ip&gt;            → PENALTY &lt;count&gt;</span></span>
<span class="line"><span>PENALTY-UPDATE &lt;ip&gt; &lt;count&gt;    → OK</span></span></code></pre></div><ul><li><code>count</code> is clamped server-side to <code>[0, MaxPenalty]</code></li><li><code>count=0</code> deletes the entry (auth-success reset)</li><li><code>count&lt;0</code> clamps to 0; <code>count&gt;MaxPenalty</code> clamps to MaxPenalty</li></ul><p>The full warden protocol is documented in <code>internal/<wbr>warden/<wbr>server.<wbr>go</code>.</p><h2 id="interaction-with-other-anti-abuse-layers" tabindex="-1">Interaction with other anti-abuse layers <a class="header-anchor" href="#interaction-with-other-anti-abuse-layers" aria-label="Permalink to &quot;Interaction with other anti-abuse layers&quot;">​</a></h2><p>The defence-in-depth stack is layered:</p><ol><li><strong>TCP / TLS layer</strong>: HAProxy rate limits, fail2ban - pre-Yarilo</li><li><strong>Connection limits</strong>: <code>mail_<wbr>max_<wbr>userip_<wbr>connections</code> enforced by <code>yarilo-warden</code> (<code>CONNECT</code> / <code>DISCONNECT</code> verbs)</li><li><strong>Auth failure delay</strong>: <code>auth.<wbr>auth_<wbr>failure_<wbr>delay</code> (2s by default) equalises timing between unknown-user and wrong-password</li><li><strong>Auth penalty</strong> (this feature): exponential backoff per IP, shared cross-pod via <code>yarilo-warden</code></li><li><strong>Policy server</strong> (<code>auth.<wbr>policy.<wbr>url</code>): external HTTP hook with pattern-detection logic - see <a href="/main/auth/policy.html">Auth Policy Server Integration</a></li></ol><p>Penalty + failure-delay compose additively: an attacker on counter=2 facing <code>auth_<wbr>failure_<wbr>delay=2s</code> waits <code>4s (penalty) + 2s (delay) = 6s</code> per attempt. Tune the two together.</p><p>Penalty + policy compose orthogonally: penalty is built-in and cheap; policy is external and rich. Operators typically enable penalty first (zero infrastructure) and add policy only when they need pattern-detection beyond per-IP counts.</p>`,31)])])}const y=t(i,[["render",l]]);export{u as __pageData,y as default};
